/**
 * Generates TypeScript types from the JSON Schemas in ../schemas.
 * Python (Pydantic) mirrors are generated by `uv run python -m fluent_agent.schemas --check`
 * which validates the same fixtures against the Pydantic models (apps/agent).
 */
import { compileFromFile } from "json-schema-to-typescript";
import { readdirSync, writeFileSync, mkdirSync } from "node:fs";
import path from "node:path";

const root = path.resolve(import.meta.dirname, "..");
const schemasDir = path.join(root, "schemas");
const outDir = path.join(root, "src", "generated");
mkdirSync(outDir, { recursive: true });

const banner =
  "/* eslint-disable */\n// AUTO-GENERATED by `pnpm shared:gen` from packages/shared/schemas — do not edit.\n";
for (const file of readdirSync(schemasDir).filter((f) => f.endsWith(".schema.json"))) {
  const ts = await compileFromFile(path.join(schemasDir, file), {
    bannerComment: banner,
    additionalProperties: false,
    style: { semi: true, singleQuote: false, printWidth: 100 },
  });
  const out = path.join(outDir, file.replace(".schema.json", ".ts"));
  writeFileSync(out, ts);
  console.log("generated", path.relative(root, out));
}
